-- MariaDB 10.11+ / MySQL 8.0.16+; InnoDB, utf8mb4, UTC dates.
CREATE TABLE IF NOT EXISTS schema_migrations (version varchar(64) PRIMARY KEY, checksum char(64) NOT NULL, applied_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS roles (name varchar(20) PRIMARY KEY CHECK(name IN ('SUPER_ADMIN','STAFF','CUSTOMER'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO roles VALUES ('SUPER_ADMIN'),('STAFF'),('CUSTOMER');
CREATE TABLE IF NOT EXISTS users (id char(36) PRIMARY KEY DEFAULT (UUID()), email varchar(254) UNIQUE NOT NULL, password_hash text NOT NULL, name varchar(120) NOT NULL, role varchar(20) NOT NULL DEFAULT 'CUSTOMER', created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (role) REFERENCES roles(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS customer_profiles (user_id char(36) PRIMARY KEY, phone text NOT NULL DEFAULT (''), address text NOT NULL DEFAULT (''), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sessions (token_hash char(64) PRIMARY KEY, user_id char(36) NOT NULL, expires_at datetime(3) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX sessions_user_idx (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS destinations (id char(36) PRIMARY KEY DEFAULT (UUID()), name varchar(100) NOT NULL UNIQUE, country varchar(80) NOT NULL DEFAULT 'Philippines', description text NOT NULL, image_url text NOT NULL, featured boolean NOT NULL DEFAULT false) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS packages (id char(36) PRIMARY KEY DEFAULT (UUID()), destination_id char(36) NOT NULL, slug varchar(150) NOT NULL UNIQUE, title varchar(200) NOT NULL, description text NOT NULL, category varchar(80) NOT NULL, duration integer NOT NULL CHECK(duration BETWEEN 1 AND 90), min_participants integer NOT NULL DEFAULT 1 CHECK(min_participants>0), max_participants integer NOT NULL DEFAULT 20 CHECK(max_participants>=min_participants), meeting_point text NOT NULL, transportation text NOT NULL, accommodation text NOT NULL, meals text NOT NULL, guide text NOT NULL, inclusions json NOT NULL DEFAULT ('[]'), exclusions json NOT NULL DEFAULT ('[]'), policies text NOT NULL, notes text NOT NULL DEFAULT (''), status varchar(80) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')), featured boolean NOT NULL DEFAULT false, demo boolean NOT NULL DEFAULT false, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (destination_id) REFERENCES destinations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS package_images (id char(36) PRIMARY KEY DEFAULT (UUID()), package_id char(36) NOT NULL, url text NOT NULL, alt text NOT NULL, position integer NOT NULL DEFAULT 0, FOREIGN KEY (package_id) REFERENCES packages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS package_pricing (package_id char(36) PRIMARY KEY, adult_price bigint NOT NULL CHECK(adult_price>0), child_price bigint NOT NULL CHECK(child_price>=0), deposit_percent integer NOT NULL DEFAULT 30 CHECK(deposit_percent BETWEEN 1 AND 100), FOREIGN KEY (package_id) REFERENCES packages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS itinerary_days (id char(36) PRIMARY KEY DEFAULT (UUID()), package_id char(36) NOT NULL, day integer NOT NULL CHECK(day>0), title varchar(200) NOT NULL, UNIQUE(package_id,day), FOREIGN KEY (package_id) REFERENCES packages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS itinerary_activities (id char(36) PRIMARY KEY DEFAULT (UUID()), day_id char(36) NOT NULL, sequence integer NOT NULL DEFAULT 0, time_label text NOT NULL, title varchar(200) NOT NULL, description text NOT NULL, location text NOT NULL DEFAULT (''), photo_url text, included boolean NOT NULL DEFAULT true, FOREIGN KEY (day_id) REFERENCES itinerary_days(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS departures (id char(36) PRIMARY KEY DEFAULT (UUID()), package_id char(36) NOT NULL, departure_at datetime(3) NOT NULL, booking_deadline datetime(3) NOT NULL, capacity integer NOT NULL CHECK(capacity>0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=capacity), price_adjustment bigint NOT NULL DEFAULT 0, available boolean NOT NULL DEFAULT true, UNIQUE(package_id,departure_at), CHECK(booking_deadline<departure_at), FOREIGN KEY (package_id) REFERENCES packages(id), INDEX departures_date_idx (departure_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS promotions (id char(36) PRIMARY KEY DEFAULT (UUID()), name varchar(120) NOT NULL, code varchar(40) NOT NULL UNIQUE, discount_type varchar(80) NOT NULL CHECK(discount_type IN ('PERCENT','FIXED')), value bigint NOT NULL CHECK(value>0), starts_at datetime(3) NOT NULL, ends_at datetime(3) NOT NULL, usage_limit integer NOT NULL CHECK(usage_limit>0), used integer NOT NULL DEFAULT 0 CHECK(used>=0 AND used<=usage_limit), min_total bigint NOT NULL DEFAULT 0 CHECK(min_total>=0), active boolean NOT NULL DEFAULT true, CHECK(ends_at>starts_at), CHECK(discount_type!='PERCENT' OR value<=100)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS promotion_packages (promotion_id char(36) NOT NULL, package_id char(36) NOT NULL, PRIMARY KEY(promotion_id,package_id), FOREIGN KEY (promotion_id) REFERENCES promotions(id) ON DELETE CASCADE, FOREIGN KEY (package_id) REFERENCES packages(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bookings (id char(36) PRIMARY KEY DEFAULT (UUID()), reference varchar(100) NOT NULL UNIQUE, user_id char(36), departure_id char(36) NOT NULL, contact_name varchar(120) NOT NULL, contact_email varchar(254) NOT NULL, contact_phone text NOT NULL, adults integer NOT NULL CHECK(adults>=1), children integer NOT NULL DEFAULT 0 CHECK(children>=0), subtotal bigint NOT NULL CHECK(subtotal>0), discount bigint NOT NULL DEFAULT 0 CHECK(discount>=0), total bigint NOT NULL CHECK(total>0), deposit_due bigint NOT NULL CHECK(deposit_due>0 AND deposit_due<=total), payment_method varchar(80) NOT NULL CHECK(payment_method IN ('GCASH','MAYA','BANK','CASH')), status varchar(80) NOT NULL DEFAULT 'PENDING_PAYMENT' CHECK(status IN ('PENDING_REVIEW','PENDING_PAYMENT','PAYMENT_UNDER_REVIEW','CONFIRMED','COMPLETED','CANCELLED','REFUND_PENDING','REFUNDED')), snapshot json NOT NULL, guest_token_hash char(64) NOT NULL, expires_at datetime(3), cancellation_reason text, seats_released boolean NOT NULL DEFAULT false, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK(total=subtotal-discount), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (departure_id) REFERENCES departures(id), INDEX bookings_user_idx (user_id), INDEX bookings_departure_idx (departure_id), INDEX bookings_status_idx (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS booking_travelers (id char(36) PRIMARY KEY DEFAULT (UUID()), booking_id char(36) NOT NULL, name varchar(120) NOT NULL, type varchar(80) NOT NULL CHECK(type IN ('ADULT','CHILD')), FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS promotion_usage (promotion_id char(36) NOT NULL, booking_id char(36) UNIQUE NOT NULL, PRIMARY KEY(promotion_id,booking_id), FOREIGN KEY (promotion_id) REFERENCES promotions(id), FOREIGN KEY (booking_id) REFERENCES bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_submissions (id char(36) PRIMARY KEY DEFAULT (UUID()), booking_id char(36) NOT NULL, amount bigint NOT NULL CHECK(amount>0), method varchar(80) NOT NULL CHECK(method IN ('GCASH','MAYA','BANK','CASH')), reference varchar(100) NOT NULL, status varchar(80) NOT NULL DEFAULT 'UNDER_REVIEW' CHECK(status IN ('UNDER_REVIEW','VERIFIED','REJECTED')), review_note text, reviewed_by char(36), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), reviewed_at datetime(3), UNIQUE(method,reference), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (reviewed_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payments (id char(36) PRIMARY KEY DEFAULT (UUID()), booking_id char(36) NOT NULL, submission_id char(36) UNIQUE, amount bigint NOT NULL CHECK(amount>0), kind varchar(80) NOT NULL CHECK(kind IN ('PAYMENT','REFUND')), reference varchar(100) NOT NULL, recorded_by char(36) NOT NULL, paid_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (submission_id) REFERENCES payment_submissions(id), INDEX payments_booking_idx (booking_id), FOREIGN KEY (recorded_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS custom_inquiries (id char(36) PRIMARY KEY DEFAULT (UUID()), user_id char(36), name varchar(120) NOT NULL, email varchar(254) NOT NULL, phone text NOT NULL, destination text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, travelers integer NOT NULL CHECK(travelers>0), budget bigint NOT NULL CHECK(budget>0), accommodation text NOT NULL, interests text NOT NULL, requests text NOT NULL DEFAULT (''), status varchar(80) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','IN_PROGRESS','QUOTED','CLOSED')), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK(end_date>=start_date), FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS inquiry_quotations (id char(36) PRIMARY KEY DEFAULT (UUID()), inquiry_id char(36) NOT NULL, amount bigint NOT NULL CHECK(amount>0), message text NOT NULL, created_by char(36) NOT NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (inquiry_id) REFERENCES custom_inquiries(id), FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS reviews (id char(36) PRIMARY KEY DEFAULT (UUID()), booking_id char(36) UNIQUE NOT NULL, user_id char(36) NOT NULL, package_id char(36) NOT NULL, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL, status varchar(80) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (booking_id) REFERENCES bookings(id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (package_id) REFERENCES packages(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifications (recipient_email varchar(254), id char(36) PRIMARY KEY DEFAULT (UUID()), user_id char(36), booking_id char(36), title varchar(200) NOT NULL, message text NOT NULL, read_at datetime(3), email_status varchar(80) NOT NULL DEFAULT 'NOT_CONFIGURED' CHECK(email_status IN ('NOT_CONFIGURED','PENDING','SENT','FAILED')), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (booking_id) REFERENCES bookings(id), INDEX notifications_user_idx (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS website_content (`key` varchar(100) PRIMARY KEY, title varchar(200) NOT NULL, body text NOT NULL, updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS app_settings (`key` varchar(100) PRIMARY KEY, value json NOT NULL, updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id char(36) PRIMARY KEY DEFAULT (UUID()), actor_id char(36) NOT NULL, action varchar(80) NOT NULL, entity_type varchar(80) NOT NULL, entity_id varchar(150) NOT NULL, detail json NOT NULL DEFAULT ('{}'), created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY (actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rate_limits (`key` varchar(100) PRIMARY KEY, count integer NOT NULL DEFAULT 1, reset_at datetime(3) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
